1	import { Injectable, BadRequestException, ForbiddenException, NotFoundException } from '@nestjs/common';
2	import { ConfigService } from '@nestjs/config';
3	import { SupabaseService } from '../supabase/supabase.service';
4	import { PagBankClient } from './pagbank.client';
5	
6	const STATUS_PAGOS = ['PAID', 'COMPLETED', 'AVAILABLE'];
7	
8	type SplitConfig = {
9	  sellerAccountId: string;
10	  platformAccountId: string;
11	  comissaoPct: number;
12	};
13	
14	type ClienteInfo = {
15	  client: PagBankClient;
16	  webhookUrl: string;
17	  splitConfig?: SplitConfig;
18	};
19	
20	@Injectable()
21	export class PagamentosService {
22	  constructor(
23	    private supabase: SupabaseService,
24	    private config: ConfigService,
25	  ) {}
26	
27	  private async buscarPedido(orderId: number) {
28	    const { data, error } = await this.supabase.client
29	      .from('orders')
30	      .select('id, total, status, restaurant_id, user_id')
31	      .eq('id', orderId)
32	      .maybeSingle();
33	
34	    if (error) throw error;
35	    if (!data) throw new NotFoundException(`Pedido ${orderId} não encontrado`);
36	    return data;
37	  }
38	
39	  private async getPagBankClient(restaurantId: number): Promise<ClienteInfo> {
40	    // Busca config do restaurante e config global da plataforma em paralelo
41	    const [{ data: restData }, { data: platData }] = await Promise.all([
42	      this.supabase.client
43	        .from('restaurants')
44	        .select('payment_config, comissao_pct')
45	        .eq('id', restaurantId)
46	        .maybeSingle(),
47	      this.supabase.client
48	        .from('platform_settings')
49	        .select('config')
50	        .eq('id', 1)
51	        .maybeSingle(),
52	    ]);
53	
54	    const cfg = (restData?.payment_config ?? {}) as Record<string, any>;
55	    const platCfg = (platData?.config ?? {}) as Record<string, any>;
56	    const comissaoPct: number = restData?.comissao_pct ?? platCfg.comissao_padrao_pct ?? 5;
57	
58	    // Platform token: DB tem prioridade sobre .env
59	    const platformToken =
60	      platCfg.pagbank_platform_token ||
61	      this.config.get<string>('PAGBANK_PLATFORM_TOKEN') ||
62	      '';
63	    const platformAccountId =
64	      platCfg.pagbank_platform_account_id ||
65	      this.config.get<string>('PAGBANK_PLATFORM_ACCOUNT_ID') ||
66	      '';
67	    const sellerAccountId: string = cfg.pagbank_seller_account_id ?? '';
68	
69	    const sandbox =
70	      platCfg.pagbank_sandbox ??
71	      (cfg.pagbank_sandbox !== undefined
72	        ? cfg.pagbank_sandbox
73	        : this.config.get('PAGBANK_SANDBOX') !== 'false');
74	
75	    const webhookUrl =
76	      cfg.pagbank_webhook_url ||
77	      this.config.get('PAGBANK_WEBHOOK_URL') ||
78	      'http://localhost:3002/pagamentos/webhook';
79	
80	    // Split habilitado: plataforma tem token + ambas as contas configuradas
81	    if (platformToken && platformAccountId && sellerAccountId) {
82	      return {
83	        client: new PagBankClient(platformToken, sandbox),
84	        webhookUrl,
85	        splitConfig: { sellerAccountId, platformAccountId, comissaoPct },
86	      };
87	    }
88	
89	    // Fallback: token próprio do restaurante (sem split automático)
90	    const token = cfg.pagbank_token || this.config.get('PAGBANK_TOKEN') || '';
91	    return { client: new PagBankClient(token, sandbox), webhookUrl };
92	  }
93	
94	  // Calcula splits em centavos: vendedor recebe (100 - comissao)%, plataforma recebe comissao%
95	  private buildSplits(valorCentavos: number, split: SplitConfig) {
96	    const adminAmount = Math.round(valorCentavos * split.comissaoPct / 100);
97	    const sellerAmount = valorCentavos - adminAmount; // resto para evitar erro de arredondamento
98	
99	    return [{
100	      method: 'FIXED' as const,
101	      receivers: [
102	        { account: { id: split.sellerAccountId }, amount: { value: sellerAmount } },
103	        { account: { id: split.platformAccountId }, amount: { value: adminAmount } },
104	      ],
105	    }];
106	  }
107	
108	  private limparCpf(cpf: string) {
109	    return cpf.replace(/\D/g, '');
110	  }
111	
112	  async criarPix(body: {
113	    order_id: number;
114	    customer: { name: string; email: string; tax_id: string };
115	  }, callerUserId: string) {
116	    const pedido = await this.buscarPedido(body.order_id);
117	    if (pedido.user_id !== callerUserId) {
118	      throw new ForbiddenException('Este pedido não pertence a você');
119	    }
120	
121	    if (pedido.status !== 'pending') {
122	      throw new BadRequestException('Pedido não está pendente de pagamento');
123	    }
124	
125	    const valorCentavos = Math.round(pedido.total * 100);
126	    const refId = `DELIVERY_${pedido.id}_${Date.now()}`;
127	    const { client: pagbank, webhookUrl, splitConfig } = await this.getPagBankClient(pedido.restaurant_id);
128	
129	    const splits = splitConfig ? this.buildSplits(valorCentavos, splitConfig) : undefined;
130	
131	    const resposta = await pagbank.criarOrdemPix({
132	      reference_id: refId,
133	      valor_centavos: valorCentavos,
134	      customer: {
135	        name: body.customer.name,
136	        email: body.customer.email,
137	        tax_id: this.limparCpf(body.customer.tax_id),
138	      },
139	      itens: [{ name: `Pedido #${pedido.id}`, quantity: 1, unit_amount: valorCentavos }],
140	      webhook_url: webhookUrl,
141	      splits,
142	    });
143	
144	    const qrCode = resposta?.qr_codes?.[0];
145	    const pixCode = qrCode?.text ?? null;
146	    const pixQrUrl = qrCode?.links?.find((l: any) => l.media === 'image/png')?.href ?? null;
147	
148	    const { data: pagamento, error } = await this.supabase.client
149	      .from('pagamentos')
150	      .insert({
151	        order_id: pedido.id,
152	        pagbank_order_id: resposta.id,
153	        tipo: 'pix',
154	        status: 'pending',
155	        valor: pedido.total,
156	        pix_code: pixCode,
157	        pix_qr_url: pixQrUrl,
158	      })
159	      .select()
160	      .single();
161	
162	    if (error) throw error;
163	
164	    return {
165	      pagamento_id: pagamento.id,
166	      pix_code: pixCode,
167	      pix_qr_url: pixQrUrl,
168	      pagbank_order_id: resposta.id,
169	      split_ativo: !!splitConfig,
170	      expira_em: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
171	    };
172	  }
173	
174	  async criarCartao(body: {
175	    order_id: number;
176	    customer: { name: string; email: string; tax_id: string };
177	    card_encrypted: string;
178	    parcelas?: number;
179	    tipo?: 'CREDIT_CARD' | 'DEBIT_CARD';
180	  }, callerUserId: string) {
181	    const pedido = await this.buscarPedido(body.order_id);
182	    if (pedido.user_id !== callerUserId) {
183	      throw new ForbiddenException('Este pedido não pertence a você');
184	    }
185	
186	    if (pedido.status !== 'pending') {
187	      throw new BadRequestException('Pedido não está pendente de pagamento');
188	    }
189	
190	    const valorCentavos = Math.round(pedido.total * 100);
191	    const refId = `DELIVERY_${pedido.id}_${Date.now()}`;
192	    const tipo = body.tipo ?? 'CREDIT_CARD';
193	    const { client: pagbank, webhookUrl, splitConfig } = await this.getPagBankClient(pedido.restaurant_id);
194	
195	    const splits = splitConfig ? this.buildSplits(valorCentavos, splitConfig) : undefined;
196	
197	    const resposta = await pagbank.criarOrdemCartao({
198	      reference_id: refId,
199	      valor_centavos: valorCentavos,
200	      customer: {
201	        name: body.customer.name,
202	        email: body.customer.email,
203	        tax_id: this.limparCpf(body.customer.tax_id),
204	      },
205	      itens: [{ name: `Pedido #${pedido.id}`, quantity: 1, unit_amount: valorCentavos }],
206	      card_encrypted: body.card_encrypted,
207	      parcelas: body.parcelas ?? 1,
208	      tipo,
209	      webhook_url: webhookUrl,
210	      splits,
211	    });
212	
213	    const charge = resposta?.charges?.[0];
214	    const statusPagamento = STATUS_PAGOS.includes(charge?.status) ? 'paid' : 'pending';
215	
216	    const { data: pagamento, error } = await this.supabase.client
217	      .from('pagamentos')
218	      .insert({
219	        order_id: pedido.id,
220	        pagbank_order_id: resposta.id,
221	        pagbank_charge_id: charge?.id ?? null,
222	        tipo: tipo === 'CREDIT_CARD' ? 'credit_card' : 'debit_card',
223	        status: statusPagamento,
224	        valor: pedido.total,
225	        pago_em: statusPagamento === 'paid' ? new Date().toISOString() : null,
226	      })
227	      .select()
228	      .single();
229	
230	    if (error) throw error;
231	
232	    if (statusPagamento === 'paid') {
233	      await this.supabase.client
234	        .from('orders')
235	        .update({ status: 'preparing', updated_at: new Date().toISOString() })
236	        .eq('id', pedido.id);
237	    }
238	
239	    return {
240	      pagamento_id: pagamento.id,
241	      status: statusPagamento,
242	      pagbank_order_id: resposta.id,
243	      charge_id: charge?.id,
244	      split_ativo: !!splitConfig,
245	    };
246	  }
247	
248	  async buscarPorPedido(orderId: number, callerUserId: string, callerRole: string) {
249	    const pedido = await this.buscarPedido(orderId);
250	    if (callerRole !== 'admin' && pedido.user_id !== callerUserId) {
251	      throw new ForbiddenException('Você não tem acesso a este pedido');
252	    }
253	
254	    const { data, error } = await this.supabase.client
255	      .from('pagamentos')
256	      .select('id, tipo, status, valor, pix_code, pix_qr_url, pagbank_order_id, pago_em, criado_em')
257	      .eq('order_id', orderId)
258	      .order('criado_em', { ascending: false });
259	
260	    if (error) throw error;
261	    return { pagamentos: data ?? [] };
262	  }
263	
264	  async processarWebhook(evento: any) {
265	    const payload = evento?.data ?? evento;
266	    const pagbankOrderId: string = payload?.id ?? payload?.reference_id;
267	    if (!pagbankOrderId) return { ignorado: true };
268	
269	    const { data: pagamento } = await this.supabase.client
270	      .from('pagamentos')
271	      .select('id, order_id, status')
272	      .eq('pagbank_order_id', pagbankOrderId)
273	      .maybeSingle();
274	
275	    if (!pagamento) return { ignorado: true, motivo: 'pagamento não encontrado' };
276	    if (pagamento.status === 'paid') return { ignorado: true, motivo: 'já processado' };
277	
278	    const { data: pedido } = await this.supabase.client
279	      .from('orders')
280	      .select('restaurant_id')
281	      .eq('id', pagamento.order_id)
282	      .maybeSingle();
283	    if (!pedido) return { ignorado: true, motivo: 'pedido não encontrado' };
284	
285	    // PagBank não assina notificações — nunca confiar no status vindo no corpo
286	    // do POST. Reconsulta a ordem direto na API do PagBank e decide a partir
287	    // dessa resposta autoritativa (evita marcar "pago" via webhook forjado).
288	    const { client } = await this.getPagBankClient(pedido.restaurant_id);
289	    const ordemReal = await client.buscarOrdem(pagbankOrderId);
290	    const detalhe = ordemReal?.charges?.[0] ?? ordemReal?.payments?.[0];
291	    if (!detalhe) return { ignorado: true };
292	
293	    const statusPagbank: string = detalhe?.status ?? '';
294	    const pago = STATUS_PAGOS.includes(statusPagbank);
295	
296	    const novoStatus = pago ? 'paid' : statusPagbank === 'DECLINED' ? 'declined' : pagamento.status;
297	
298	    await this.supabase.client
299	      .from('pagamentos')
300	      .update({
301	        status: novoStatus,
302	        pagbank_charge_id: detalhe?.id ?? null,
303	        pago_em: pago ? new Date().toISOString() : null,
304	        webhook_recebido_em: new Date().toISOString(),
305	        atualizado_em: new Date().toISOString(),
306	      })
307	      .eq('id', pagamento.id);
308	
309	    if (pago) {
310	      await this.supabase.client
311	        .from('orders')
312	        .update({ status: 'preparing', updated_at: new Date().toISOString() })
313	        .eq('id', pagamento.order_id);
314	    }
315	
316	    return { processado: true, status: novoStatus, order_id: pagamento.order_id };
317	  }
318	}
