1	import React, { useState, useEffect, useRef } from 'react';
2	import Icon from '../../components/AppIcon';
3	import { confirmarEntrega, registrarOcorrencia, uploadComprovantePix } from '../../services/motoboyService';
4	import { gerarPixPayload, qrCodeUrl } from '../../utils/pixQrCode';
5	
6	const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
7	
8	// etapas: scan → pagamento → troco | exato | pix | pix_parcial → acao → ocorrencia
9	
10	const EntregaBarcode = ({ pedido, onConfirmado, chavePix, restauranteNome, restauranteCidade }) => {
11	  const [etapa, setEtapa] = useState('scan');
12	  const [scanning, setScanning] = useState(false);
13	  const [manual, setManual] = useState('');
14	  const [confirmando, setConfirmando] = useState(false);
15	  const [motivo, setMotivo] = useState('');
16	  const [trocoConfirmado, setTrocoConfirmado] = useState(false);
17	  const [exatoConfirmado, setExatoConfirmado] = useState(false);
18	  const [dinheiroInput, setDinheiroInput] = useState('');
19	  const [comprovantePreview, setComprovantePreview] = useState(null);
20	  const [comprovanteBase64, setComprovanteBase64] = useState(null);
21	  const [uploadandoFoto, setUploadandoFoto] = useState(false);
22	  const [erro, setErro] = useState(null);
23	  const scannerRef = useRef(null);
24	  const fileInputRef = useRef(null);
25	  const divId = `entrega-scan-${pedido.id}`;
26	
27	  const expectedCode = String(pedido.id).padStart(8, '0');
28	  const temTroco = pedido.payment_method === 'cash' && Number(pedido.troco_para) > Number(pedido.total);
29	  const trocoValor = temTroco ? Number(pedido.troco_para) - Number(pedido.total) : 0;
30	  const total = Number(pedido.total);
31	
32	  const validarCodigo = (code) => code.replace(/\D/g, '').padStart(8, '0') === expectedCode;
33	
34	  const stopScan = async () => {
35	    try { if (scannerRef.current?.isScanning) await scannerRef.current.stop(); } catch {}
36	    scannerRef.current = null;
37	    setScanning(false);
38	  };
39	
40	  const handleScanSuccess = (decoded) => {
41	    stopScan();
42	    if (!validarCodigo(decoded)) { setErro(`Código não corresponde ao pedido #${pedido.id}`); return; }
43	    setErro(null);
44	    setEtapa('pagamento');
45	  };
46	
47	  const startScan = async () => {
48	    setErro(null);
49	    try {
50	      const { Html5Qrcode } = await import('html5-qrcode');
51	      scannerRef.current = new Html5Qrcode(divId);
52	      setScanning(true);
53	      await scannerRef.current.start(
54	        { facingMode: 'environment' },
55	        { fps: 10, qrbox: { width: 220, height: 220 } },
56	        (decoded) => handleScanSuccess(decoded),
57	        () => {},
58	      );
59	    } catch {
60	      setScanning(false);
61	      setErro('Câmera indisponível. Use o campo manual.');
62	    }
63	  };
64	
65	  useEffect(() => () => { stopScan(); }, []); // eslint-disable-line
66	
67	  const handleOcorrencia = async () => {
68	    if (motivo.trim().length < 10) return;
69	    setConfirmando(true);
70	    try { await registrarOcorrencia(pedido.id, 'pendente', motivo.trim()); onConfirmado(); }
71	    catch (e) { setErro(e.message); }
72	    finally { setConfirmando(false); }
73	  };
74	
75	  // Gera QR PIX para o valor especificado
76	  const pixQr = (valor) => {
77	    if (!chavePix) return null;
78	    const payload = gerarPixPayload({
79	      chave: chavePix,
80	      nome: restauranteNome,
81	      cidade: restauranteCidade,
82	      valor,
83	      txid: `ped${pedido.id}`,
84	    });
85	    return qrCodeUrl(payload);
86	  };
87	
88	  const dinheiroVal = parseFloat(dinheiroInput.replace(',', '.')) || 0;
89	  const pixParcialVal = dinheiroVal > 0 && dinheiroVal < total ? total - dinheiroVal : 0;
90	
91	  const comprimirImagem = (file) =>
92	    new Promise((resolve) => {
93	      const img = new Image();
94	      const url = URL.createObjectURL(file);
95	      img.onload = () => {
96	        const MAX = 1200;
97	        const scale = Math.min(1, MAX / Math.max(img.width, img.height));
98	        const canvas = document.createElement('canvas');
99	        canvas.width = img.width * scale;
100	        canvas.height = img.height * scale;
101	        canvas.getContext('2d').drawImage(img, 0, 0, canvas.width, canvas.height);
102	        URL.revokeObjectURL(url);
103	        resolve(canvas.toDataURL('image/jpeg', 0.75));
104	      };
105	      img.src = url;
106	    });
107	
108	  const handleFotoChange = async (e) => {
109	    const file = e.target.files?.[0];
110	    if (!file) return;
111	    const base64 = await comprimirImagem(file);
112	    setComprovanteBase64(base64);
113	    setComprovantePreview(base64);
114	    e.target.value = '';
115	  };
116	
117	  const handleEntregar = async (entregaPagamento) => {
118	    setConfirmando(true);
119	    try {
120	      if (comprovanteBase64) {
121	        setUploadandoFoto(true);
122	        await uploadComprovantePix(pedido.id, comprovanteBase64);
123	        setUploadandoFoto(false);
124	      }
125	      await confirmarEntrega(pedido.id, entregaPagamento);
126	      onConfirmado();
127	    } catch (e) {
128	      setErro(e.message);
129	    } finally {
130	      setConfirmando(false);
131	      setUploadandoFoto(false);
132	    }
133	  };
134	
135	  return (
136	    <div className="border-t border-[#E4E4E7] dark:border-[#3F3F46] pt-3 space-y-3">
137	
138	      {/* ETAPA: SCAN */}
139	      {etapa === 'scan' && (
140	        <>
141	          <p className="text-xs font-semibold text-green-700 dark:text-green-400 text-center bg-green-50 dark:bg-green-950/30 rounded-xl px-3 py-2">
142	            Escaneie o código da comanda para confirmar entrega
143	          </p>
144	          <div id={divId} className={`rounded-xl overflow-hidden ${scanning ? 'block' : 'hidden'}`} />
145	          {!scanning ? (
146	            <button onClick={startScan}
147	              className="w-full py-3 bg-green-600 hover:bg-green-700 text-white font-bold text-sm rounded-xl flex items-center justify-center gap-2">
148	              <Icon name="ScanLine" size={16} /> Escanear comanda (câmera)
149	            </button>
150	          ) : (
151	            <button onClick={stopScan} className="w-full py-2 bg-[#F4F4F5] dark:bg-[#3F3F46] text-[#27272A] dark:text-[#F4F4F5] text-sm rounded-xl">
152	              Cancelar scan
153	            </button>
154	          )}
155	          <div className="flex gap-2">
156	            <input value={manual} onChange={(e) => setManual(e.target.value)}
157	              onKeyDown={(e) => e.key === 'Enter' && validarCodigo(manual) && setEtapa('pagamento')}
158	              placeholder={`Código manual (${expectedCode})`}
159	              className="flex-1 border border-[#E4E4E7] dark:border-[#3F3F46] rounded-xl px-3 py-2 text-sm font-mono focus:outline-none focus:border-green-500" />
160	            <button
161	              onClick={() => { if (validarCodigo(manual)) { setErro(null); setEtapa('pagamento'); } else setErro('Código incorreto'); }}
162	              disabled={!manual.trim()}
163	              className="px-4 py-2 bg-green-600 text-white text-sm font-bold rounded-xl disabled:opacity-50 hover:bg-green-700">
164	              OK
165	            </button>
166	          </div>
167	        </>
168	      )}
169	
170	      {/* ETAPA: ESCOLHA DE PAGAMENTO */}
171	      {etapa === 'pagamento' && (
172	        <>
173	          <p className="text-xs font-semibold text-center text-[#18181B] dark:text-[#F4F4F5] bg-green-50 dark:bg-green-950/30 rounded-xl px-3 py-2">
174	            ✅ Código confirmado — Como o cliente vai pagar?
175	          </p>
176	          <div className="space-y-2">
177	            <button
178	              onClick={() => setEtapa(temTroco ? 'troco' : 'acao')}
179	              className="w-full py-3 bg-green-600 hover:bg-green-700 text-white font-bold text-sm rounded-xl flex items-center justify-center gap-2 transition-colors">
180	              <Icon name="CheckCircle2" size={16} /> Conforme pedido
181	              {temTroco && <span className="text-xs opacity-80">({fmt(pedido.troco_para)} → troco {fmt(trocoValor)})</span>}
182	            </button>
183	
184	            <button
185	              onClick={() => setEtapa('exato')}
186	              className="w-full py-3 border-2 border-green-200 dark:border-green-800 bg-green-50 dark:bg-green-950/30 text-green-800 dark:text-green-300 font-bold text-sm rounded-xl flex items-center justify-center gap-2 hover:bg-green-100 dark:hover:bg-green-950/40 transition-colors">
187	              <Icon name="Banknote" size={16} /> Cliente pagou valor exato — sem troco
188	            </button>
189	
190	            {chavePix ? (
191	              <>
192	                <button
193	                  onClick={() => setEtapa('pix')}
194	                  className="w-full py-3 border-2 border-blue-200 dark:border-blue-800 bg-blue-50 dark:bg-blue-950/30 text-blue-800 dark:text-blue-300 font-bold text-sm rounded-xl flex items-center justify-center gap-2 hover:bg-blue-100 dark:hover:bg-blue-950/40 transition-colors">
195	                  <Icon name="QrCode" size={16} /> Cliente quer pagar com PIX
196	                </button>
197	                <button
198	                  onClick={() => setEtapa('pix_parcial')}
199	                  className="w-full py-3 border-2 border-purple-200 dark:border-purple-800 bg-purple-50 dark:bg-purple-950/30 text-purple-800 dark:text-purple-300 font-bold text-sm rounded-xl flex items-center justify-center gap-2 hover:bg-purple-100 dark:hover:bg-purple-950/40 transition-colors">
200	                  <Icon name="Split" size={16} /> Dinheiro + PIX (combinado)
201	                </button>
202	              </>
203	            ) : (
204	              <p className="text-xs text-[#A1A1AA] dark:text-[#71717A] text-center bg-[#F4F4F5] dark:bg-[#3F3F46] rounded-xl px-3 py-2">
205	                PIX indisponível — chave não configurada no restaurante
206	              </p>
207	            )}
208	          </div>
209	          <button onClick={() => setEtapa('ocorrencia')}
210	            className="w-full py-2.5 bg-orange-500 hover:bg-orange-600 text-white font-bold text-sm rounded-xl flex items-center justify-center gap-2 transition-colors">
211	            <Icon name="Clock" size={14} /> Não consegui entregar (pendência)
212	          </button>
213	        </>
214	      )}
215	
216	      {/* ETAPA: TROCO */}
217	      {etapa === 'troco' && (
218	        <>
219	          <div className="bg-amber-50 dark:bg-amber-950/30 border-2 border-amber-300 dark:border-amber-700 rounded-xl p-4 space-y-3">
220	            <p className="text-sm font-black text-amber-800 dark:text-amber-300 text-center">Confirmação de Troco</p>
221	            <div className="flex justify-between text-sm">
222	              <span className="text-amber-700 dark:text-amber-400">Receber do cliente:</span>
223	              <strong className="text-amber-900 dark:text-amber-200">{fmt(pedido.troco_para)}</strong>
224	            </div>
225	            <div className="flex justify-between text-sm">
226	              <span className="text-amber-700 dark:text-amber-400">Devolver de troco:</span>
227	              <strong className="text-amber-900 dark:text-amber-200">{fmt(trocoValor)}</strong>
228	            </div>
229	            <label className="flex items-start gap-3 cursor-pointer">
230	              <input type="checkbox" checked={trocoConfirmado}
231	                onChange={(e) => setTrocoConfirmado(e.target.checked)}
232	                className="mt-0.5 w-5 h-5 accent-amber-500 flex-shrink-0" />
233	              <span className="text-xs text-amber-900 dark:text-amber-200 leading-snug font-medium">
234	                Confirmo que recebi <strong>{fmt(pedido.troco_para)}</strong> e passei <strong>{fmt(trocoValor)}</strong> de troco
235	              </span>
236	            </label>
237	          </div>
238	          <button
239	            onClick={() => handleEntregar({ metodo: 'conforme', dinheiro: Number(pedido.troco_para) })}
240	            disabled={!trocoConfirmado || confirmando}
241	            className="w-full py-3 bg-green-600 hover:bg-green-700 text-white font-black text-sm rounded-xl disabled:opacity-50 flex items-center justify-center gap-2 transition-colors">
242	            <Icon name="CheckCircle2" size={16} /> {confirmando ? 'Confirmando...' : 'Confirmar e Marcar Entregue'}
243	          </button>
244	          <button onClick={() => setEtapa('pagamento')} className="w-full py-2 text-xs text-[#71717A] dark:text-[#A1A1AA] hover:text-[#18181B] dark:hover:text-[#F4F4F5]">
245	            ← Voltar
246	          </button>
247	        </>
248	      )}
249	
250	      {/* ETAPA: VALOR EXATO */}
251	      {etapa === 'exato' && (
252	        <>
253	          <div className="bg-green-50 dark:bg-green-950/30 border-2 border-green-300 dark:border-green-700 rounded-xl p-4 space-y-3">
254	            <p className="text-sm font-black text-green-800 dark:text-green-300 text-center">Confirmar Recebimento</p>
255	            <div className="flex justify-between text-sm">
256	              <span className="text-green-700 dark:text-green-400">Valor recebido:</span>
257	              <strong className="text-green-900 dark:text-green-200">{fmt(total)}</strong>
258	            </div>
259	            <label className="flex items-start gap-3 cursor-pointer">
260	              <input type="checkbox" checked={exatoConfirmado}
261	                onChange={(e) => setExatoConfirmado(e.target.checked)}
262	                className="mt-0.5 w-5 h-5 accent-green-500 flex-shrink-0" />
263	              <span className="text-xs text-green-900 dark:text-green-200 leading-snug font-medium">
264	                Confirmo que recebi <strong>{fmt(total)}</strong> em dinheiro, valor exato, sem troco
265	              </span>
266	            </label>
267	          </div>
268	          <button
269	            onClick={() => handleEntregar({ metodo: 'exato', dinheiro: total })}
270	            disabled={!exatoConfirmado || confirmando}
271	            className="w-full py-3 bg-green-600 hover:bg-green-700 text-white font-black text-sm rounded-xl disabled:opacity-50 flex items-center justify-center gap-2 transition-colors">
272	            <Icon name="CheckCircle2" size={16} /> {confirmando ? 'Confirmando...' : 'Entregue!'}
273	          </button>
274	          <button onClick={() => setEtapa('pagamento')} className="w-full py-2 text-xs text-[#71717A] dark:text-[#A1A1AA] hover:text-[#18181B] dark:hover:text-[#F4F4F5]">
275	            ← Voltar
276	          </button>
277	        </>
278	      )}
279	
280	      {/* Input câmera oculto — compartilhado pelas etapas PIX */}
281	      <input
282	        ref={fileInputRef}
283	        type="file"
284	        accept="image/*"
285	        capture="environment"
286	        className="hidden"
287	        onChange={handleFotoChange}
288	      />
289	
290	      {/* ETAPA: PIX TOTAL */}
291	      {etapa === 'pix' && (
292	        <>
293	          <p className="text-sm font-black text-blue-800 dark:text-blue-300 text-center">PIX — {fmt(total)}</p>
294	          {pixQr(total) ? (
295	            <div className="flex flex-col items-center gap-2">
296	              <img src={pixQr(total)} alt="QR Code PIX" className="w-[220px] h-[220px] rounded-xl border border-blue-200 dark:border-blue-800" />
297	              <p className="text-xs text-blue-700 dark:text-blue-400 text-center">Cliente escaneia com o app do banco</p>
298	            </div>
299	          ) : (
300	            <p className="text-xs text-red-500 dark:text-red-400 text-center">Erro ao gerar QR Code</p>
301	          )}
302	
303	          {/* Comprovante */}
304	          {comprovantePreview ? (
305	            <div className="relative">
306	              <img src={comprovantePreview} alt="Comprovante" className="w-full max-h-40 object-cover rounded-xl border-2 border-green-300 dark:border-green-700" />
307	              <button
308	                onClick={() => { setComprovantePreview(null); setComprovanteBase64(null); }}
309	                className="absolute top-1 right-1 bg-white dark:bg-[#27272A] rounded-full p-1 shadow">
310	                <Icon name="X" size={14} className="text-gray-600" />
311	              </button>
312	              <p className="text-xs text-green-700 dark:text-green-400 text-center mt-1 font-semibold">✓ Comprovante capturado</p>
313	            </div>
314	          ) : (
315	            <button
316	              onClick={() => fileInputRef.current?.click()}
317	              className="w-full py-2.5 border-2 border-dashed border-blue-300 dark:border-blue-700 bg-blue-50 dark:bg-blue-950/30 text-blue-700 dark:text-blue-400 font-bold text-sm rounded-xl flex items-center justify-center gap-2 hover:bg-blue-100 dark:hover:bg-blue-950/40 transition-colors">
318	              <Icon name="Camera" size={16} /> Fotografar comprovante do cliente
319	            </button>
320	          )}
321	
322	          <button
323	            onClick={() => handleEntregar({ metodo: 'pix', pix: total })}
324	            disabled={confirmando}
325	            className="w-full py-3 bg-green-600 hover:bg-green-700 text-white font-black text-sm rounded-xl disabled:opacity-50 flex items-center justify-center gap-2 transition-colors">
326	            <Icon name="CheckCircle2" size={16} />
327	            {uploadandoFoto ? 'Enviando foto...' : confirmando ? 'Confirmando...' : 'PIX Recebido — Marcar Entregue'}
328	          </button>
329	          <button onClick={() => setEtapa('pagamento')} className="w-full py-2 text-xs text-[#71717A] dark:text-[#A1A1AA] hover:text-[#18181B] dark:hover:text-[#F4F4F5]">
330	            ← Voltar
331	          </button>
332	        </>
333	      )}
334	
335	      {/* ETAPA: PIX PARCIAL (dinheiro + PIX) */}
336	      {etapa === 'pix_parcial' && (
337	        <>
338	          <p className="text-sm font-black text-purple-800 dark:text-purple-300 text-center">Dinheiro + PIX — Total {fmt(total)}</p>
339	          <div className="space-y-2">
340	            <p className="text-xs text-[#71717A] dark:text-[#A1A1AA] font-medium">Quanto o cliente paga em dinheiro?</p>
341	            <input
342	              type="number" step="0.01" min="0.01" max={total - 0.01}
343	              value={dinheiroInput}
344	              onChange={(e) => setDinheiroInput(e.target.value)}
345	              placeholder="Ex: 10,00"
346	              className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-purple-400"
347	            />
348	            {pixParcialVal > 0 && (
349	              <>
350	                <div className="flex justify-between text-sm bg-purple-50 dark:bg-purple-950/30 rounded-xl px-3 py-2">
351	                  <span className="text-purple-700 dark:text-purple-400">Dinheiro:</span>
352	                  <strong className="text-purple-900 dark:text-purple-200">{fmt(dinheiroVal)}</strong>
353	                </div>
354	                <div className="flex justify-between text-sm bg-blue-50 dark:bg-blue-950/30 rounded-xl px-3 py-2">
355	                  <span className="text-blue-700 dark:text-blue-400">PIX a cobrar:</span>
356	                  <strong className="text-blue-900 dark:text-blue-200">{fmt(pixParcialVal)}</strong>
357	                </div>
358	                {pixQr(pixParcialVal) && (
359	                  <div className="flex flex-col items-center gap-2 mt-1">
360	                    <img src={pixQr(pixParcialVal)} alt="QR Code PIX parcial" className="w-[200px] h-[200px] rounded-xl border border-blue-200 dark:border-blue-800" />
361	                    <p className="text-xs text-blue-700 dark:text-blue-400 text-center">Cliente escaneia para pagar {fmt(pixParcialVal)}</p>
362	                  </div>
363	                )}
364	              </>
365	            )}
366	          </div>
367	          <button
368	            onClick={() => handleEntregar({ metodo: 'pix_parcial', dinheiro: dinheiroVal, pix: pixParcialVal })}
369	            disabled={confirmando || pixParcialVal <= 0}
370	            className="w-full py-3 bg-green-600 hover:bg-green-700 text-white font-black text-sm rounded-xl disabled:opacity-50 flex items-center justify-center gap-2 transition-colors">
371	            <Icon name="CheckCircle2" size={16} /> {confirmando ? 'Confirmando...' : 'Pagamento Recebido — Entregue'}
372	          </button>
373	          <button onClick={() => setEtapa('pagamento')} className="w-full py-2 text-xs text-[#71717A] dark:text-[#A1A1AA] hover:text-[#18181B] dark:hover:text-[#F4F4F5]">
374	            ← Voltar
375	          </button>
376	        </>
377	      )}
378	
379	      {/* ETAPA: AÇÃO FINAL */}
380	      {etapa === 'acao' && (
381	        <>
382	          <p className="text-xs font-semibold text-center text-[#18181B] dark:text-[#F4F4F5] bg-green-50 dark:bg-green-950/30 rounded-xl px-3 py-2">
383	            ✅ Confirme a entrega do pedido #{pedido.id}
384	          </p>
385	          <button
386	            onClick={() => handleEntregar({ metodo: 'conforme', dinheiro: total })}
387	            disabled={confirmando}
388	            className="w-full py-3 bg-green-600 hover:bg-green-700 text-white font-black text-sm rounded-xl disabled:opacity-50 flex items-center justify-center gap-2">
389	            <Icon name="CheckCircle2" size={16} />
390	            {confirmando ? 'Confirmando...' : 'Entregue!'}
391	          </button>
392	          <button onClick={() => setEtapa('ocorrencia')} disabled={confirmando}
393	            className="w-full py-3 bg-orange-500 hover:bg-orange-600 text-white font-bold text-sm rounded-xl disabled:opacity-50 flex items-center justify-center gap-2">
394	            <Icon name="Clock" size={14} /> Não consegui entregar (pendência)
395	          </button>
396	          <button onClick={() => setEtapa('pagamento')} className="w-full py-2 text-xs text-[#71717A] dark:text-[#A1A1AA] hover:text-[#18181B] dark:hover:text-[#F4F4F5]">
397	            ← Voltar
398	          </button>
399	        </>
400	      )}
401	
402	      {/* ETAPA: OCORRÊNCIA */}
