404	        <>
405	          <p className="text-xs font-bold text-orange-700 dark:text-orange-400 mb-1">Descreva o motivo da pendência:</p>
406	          <textarea value={motivo} onChange={(e) => setMotivo(e.target.value)} rows={3}
407	            placeholder="Ex: Cliente não atendeu, endereço incorreto..."
408	            className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-orange-400 resize-none" />
409	          <div className="flex gap-2">
410	            <button onClick={() => setEtapa('acao')}
411	              className="flex-1 py-2.5 text-sm border border-[#E4E4E7] dark:border-[#3F3F46] rounded-xl text-[#71717A] dark:text-[#A1A1AA] hover:bg-[#F4F4F5] dark:hover:bg-[#3F3F46]">
412	              Voltar
413	            </button>
