415	              className="flex-1 py-2.5 text-sm bg-orange-500 text-white rounded-xl font-bold hover:bg-orange-600 disabled:opacity-50">
416	              {confirmando ? '...' : 'Registrar'}
417	            </button>
418	          </div>
